// ── THUNDER SYSTEM AI INLINE COMPONENT ────────────────────────────────────────
interface ConsoleLine {
  text: string;
  type: "input" | "output" | "error" | "success" | "header";
}

interface ChatMessage {
  role: "user" | "assistant";
  content: string;
}

function ThunderAISection() {
  const [inputVal, setInputVal] = useState("");
  const [isProcessing, setIsProcessing] = useState(false);
  const [chatHistory, setChatHistory] = useState<ChatMessage[]>([]);
  const [cmdHistory, setCmdHistory] = useState<string[]>([]);
  const [historyIndex, setHistoryIndex] = useState(-1);
  const [consoleLines, setConsoleLines] = useState<ConsoleLine[]>([
    { text: "⚡ THUNDER SYSTEM AI v2.0 — COGNITIVE DEVOPS INTELLIGENCE CONSOLE", type: "header" },
    { text: "[ SYSTEMS ONLINE ] Gemini 2.5 Flash neural grid synchronized.", type: "success" },
    { text: "Type 'help' for commands, or ask anything about Gowtham's projects.", type: "output" },
    { text: "", type: "output" },
  ]);

  const bottomRef = useRef<HTMLDivElement>(null);
  const inputRef = useRef<HTMLInputElement>(null);

  useEffect(() => {
    bottomRef.current?.scrollIntoView({ behavior: "smooth" });
  }, [consoleLines]);

  const focusInput = () => inputRef.current?.focus();

  const handleKeyDown = (e: React.KeyboardEvent<HTMLInputElement>) => {
    if (e.key === "ArrowUp") {
      e.preventDefault();
      const next = historyIndex + 1;
      if (next < cmdHistory.length) { setHistoryIndex(next); setInputVal(cmdHistory[next]); }
    } else if (e.key === "ArrowDown") {
      e.preventDefault();
      const next = historyIndex - 1;
      if (next >= 0) { setHistoryIndex(next); setInputVal(cmdHistory[next]); }
      else { setHistoryIndex(-1); setInputVal(""); }
    }
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (isProcessing) return;
    const cmd = inputVal.trim();
    if (!cmd) return;

    setCmdHistory(prev => [cmd, ...prev]);
    setHistoryIndex(-1);

    const userLine = `visitor@thunder:~$ ${cmd}`;
    const newLines: ConsoleLine[] = [...consoleLines, { text: userLine, type: "input" }];
    setConsoleLines(newLines);
    setInputVal("");

    const q = cmd.toLowerCase().trim();

    if (q === "clear") { setConsoleLines([]); return; }
    if (q === "help") {
      setConsoleLines(prev => [...prev, {
        text: `THUNDER SYSTEM — COMMAND MANUAL:
  recruiter_mode     → Instant executive summary for recruiters
  roadmap            → Display learning milestones
  explain <project>  → Deep-dive any project architecture
  resume             → 30-second elevator pitch
  thunder breathing  → ⚡ Easter egg
  contact            → Communication portals
  clear              → Reset terminal

Or just ask naturally: "What projects has Gowtham done?"`,
        type: "output"
      }]);
      return;
    }
    if (q === "contact") {
      setConsoleLines(prev => [...prev, {
        text: `COMMUNICATION PORTALS:
  Email    : gowthamsasuke2005@gmail.com
  LinkedIn : linkedin.com/in/gowtham-b
  GitHub   : github.com/B-Gowtham-1`,
        type: "success"
      }]);
      return;
    }

    // AI Route
    setIsProcessing(true);
    setConsoleLines(prev => [...prev, { text: `⚡ THUNDER AI: Processing [${cmd}]...`, type: "header" }]);

    try {
      const updated: ChatMessage[] = [...chatHistory, { role: "user" as const, content: cmd }];
      const res = await fetch("/api/gemini", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ messages: updated }),
      });
      const data = await res.json();
      if (!res.ok || data.error) {
        setConsoleLines(prev => [...prev.slice(0, -1), { text: `[ ERROR ] ${data.error || "Connection fault."}`, type: "error" }]);
      } else {
        setChatHistory([...updated, { role: "assistant" as const, content: data.text }]);
        setConsoleLines(prev => [...prev.slice(0, -1), { text: data.text, type: "output" }]);
      }
    } catch {
      setConsoleLines(prev => [...prev.slice(0, -1), { text: "[ ERROR ] Network connection fault.", type: "error" }]);
    } finally {
      setIsProcessing(false);
    }
  };

  return (
    <section
      id="ai"
      className="max-w-7xl mx-auto w-full px-4 sm:px-6 lg:px-8 py-16 sm:py-24 border-b border-zenitsu-gray/45 space-y-8"
    >
      {/* Header */}
      <div className="text-center space-y-3">
        <span className="text-[10px] text-zenitsu-yellow font-bold tracking-widest font-mono uppercase block">
          // THUNDER_SYSTEM_COGNITIVE_AI
        </span>
        <h2 className="text-2xl sm:text-3xl font-black font-orbitron text-zenitsu-light tracking-wider uppercase flex items-center justify-center gap-3">
          <Zap className="h-7 w-7 text-zenitsu-yellow animate-thunder-blink" />
          THUNDER SYSTEM AI
        </h2>
        <p className="text-xs text-gray-500 font-mono uppercase tracking-widest max-w-xl mx-auto">
          Powered by Gemini 2.5 Flash — Ask about projects, get recruiter summary, explore the DevOps roadmap
        </p>
      </div>

      {/* Quick Action Buttons */}
      <div className="flex flex-wrap justify-center gap-2">
        {[
          { label: "⚡ RECRUITER MODE", cmd: "recruiter_mode" },
          { label: "🗺️ ROADMAP", cmd: "roadmap" },
          { label: "🐳 EXPLAIN DOCKER PROJECT", cmd: "explain multi-stage docker builds" },
          { label: "🔧 EXPLAIN JENKINS", cmd: "explain jenkins pipeline" },
          { label: "☁️ AWS PROJECTS", cmd: "What AWS projects has Gowtham built?" },
          { label: "📄 RESUME", cmd: "resume" },
        ].map((btn) => (
          <button
            key={btn.cmd}
            onClick={() => {
              setInputVal(btn.cmd);
              setTimeout(() => inputRef.current?.focus(), 100);
            }}
            className="px-3 py-1.5 border border-zenitsu-yellow/30 bg-zenitsu-glow text-[9px] text-zenitsu-yellow font-bold uppercase tracking-widest font-mono hover:bg-zenitsu-yellow/10 hover:border-zenitsu-yellow/60 transition-all"
          >
            {btn.label}
          </button>
        ))}
      </div>

      {/* Terminal Console */}
      <div
        onClick={focusInput}
        className="bg-zenitsu-darkest border-2 border-zenitsu-gray hover:border-zenitsu-yellow/30 transition-colors p-4 sm:p-6 flex flex-col cursor-text relative rounded-sm min-h-[380px] max-h-[520px] overflow-hidden"
        style={{ boxShadow: '0 0 40px rgba(255,215,0,0.05)' }}
      >
        {/* Scanline overlay */}
        <div className="absolute inset-0 bg-[linear-gradient(rgba(18,16,16,0)_50%,rgba(0,0,0,0.18)_50%)] bg-[length:100%_4px] pointer-events-none opacity-20 z-20" />

        {/* Terminal output */}
        <div className="flex-grow overflow-y-auto space-y-2 pb-4 z-10 pr-1" style={{ scrollbarWidth: 'thin', scrollbarColor: '#161616 transparent' }}>
          {consoleLines.map((line, idx) => {
            let cls = "text-gray-300";
            if (line.type === "header") cls = "text-zenitsu-yellow font-black";
            else if (line.type === "input") cls = "text-zenitsu-light font-bold";
            else if (line.type === "success") cls = "text-green-400 font-bold";
            else if (line.type === "error") cls = "text-zenitsu-orange font-bold animate-pulse";
            return (
              <pre key={idx} className={`text-xs whitespace-pre-wrap leading-relaxed font-mono ${cls}`}>
                {line.text}
              </pre>
            );
          })}
          <div ref={bottomRef} />
        </div>

        {/* Input row */}
        <form onSubmit={handleSubmit} className="flex items-center gap-3 pt-3 border-t border-zenitsu-gray z-10 flex-shrink-0">
          <span className="text-xs font-bold text-zenitsu-yellow animate-pulse font-mono flex-shrink-0">
            visitor@thunder:~$
          </span>
          <input
            ref={inputRef}
            type="text"
            value={inputVal}
            onChange={e => setInputVal(e.target.value)}
            onKeyDown={handleKeyDown}
            disabled={isProcessing}
            className="flex-grow bg-transparent text-xs text-zenitsu-light focus:outline-none border-none p-0 font-mono disabled:opacity-40"
            placeholder={isProcessing ? "THUNDER AI scanning..." : "Ask anything or type 'help'..."}
            autoComplete="off"
            maxLength={200}
          />
          <span className="text-[9px] text-gray-600 font-mono flex items-center gap-1 flex-shrink-0">
            {isProcessing ? (
              <><Loader2 className="h-3 w-3 text-zenitsu-yellow animate-spin" /> AI PROCESSING...</>
            ) : (
              <><ShieldCheck className="h-3 w-3 text-green-500" /> ONLINE</>
            )}
          </span>
        </form>
      </div>

      {/* Bottom note */}
      <p className="text-center text-[9px] text-gray-600 font-mono uppercase tracking-widest">
        [ THUNDER SYSTEM AI ] — Powered by Gemini 2.5 Flash · No login required · Open to all visitors
      </p>
    </section>
  );
}
